# Bestehende 8 Crews (Namen/Profile der alten Gegner bleiben, wo sie passen)
# Persona: (model/key, Name, Nick DE, Nick EN, Profil DE, Profil EN[, Lack])
CREWS_A = [
dict(id='t_lantern', name='Mayonaka Lanterns', jp='真夜中ランタン', color='#ffb347', tier=0, region='shinagawa',
 desc=('Studenten aus Shibuya, die nachts mit ihren ersten Autos den Ring abfahren. Laut, frech, aber ohne viel Erfahrung.',
       'Students from Shibuya cruising the loop at night in their first cars. Loud and cocky, but short on experience.'),
 leader=('covet/15zxi_M', 'Riku Tanabe', 'Laternenträger', 'Lantern Bearer',
   'Gründer der Lanterns. Nimmt jeden Neuling persönlich unter die Lupe und vergibt Noten von 1 bis 6.',
   'Founder of the Lanterns. Personally inspects every rookie and hands out school grades.', 'orange'),
 members=[
  ('covet/15se_M', 'Kenta Mori', 'Der Lehrling', 'The Apprentice', 'Hat den Führerschein seit drei Wochen. Der Fahrlehrer ruft immer noch jeden Abend an.', 'Got his licence three weeks ago. His driving instructor still calls him every night.'),
  ('covet/15le_A', 'Yui Sakamoto', 'Pinke Laterne', 'Pink Lantern', 'Fährt mit Lichterkette im Innenraum. Bei Rot blinkt sie im Takt.', 'Drives with fairy lights inside. At red lights they blink to the beat.', 'pink'),
  ('covet/type_L_M', 'Daichi Ono', 'Bremslicht', 'Brake Light', 'Bremst immer einen Tick zu früh. Und dann noch mal, zur Sicherheit.', 'Always brakes a little too early. Then once more, just to be safe.'),
  ('covet/type_L_A', 'Haruto Ishii', 'Kassettenkind', 'Tape Kid', 'Fährt nur mit Eurobeat vom Tape. Wenn das Band reißt, ist das Rennen vorbei.', 'Only drives to Eurobeat on cassette. If the tape snaps, the race is over.'),
  ('covet/13s_M', 'Sora Takeda', 'Sparschwein', 'Piggy Bank', 'Hat seinen 13S mit Pfandflaschen bezahlt. Jedes Rennen kostet ihn emotional ein Vermögen.', 'Paid for his 13S with bottle deposits. Every race costs him a fortune emotionally.'),
  ('covet/15se_A', 'Mei Arakawa', 'Mensa-Queen', 'Cafeteria Queen', 'Hat im Handschuhfach immer drei Onigiri. Teilt sie nur mit Leuten, die sie geschlagen haben.', 'Always keeps three onigiri in the glovebox. Only shares them with people who beat her.', 'mint'),
  ('covet/15ee_m', 'Yuma Kogure', 'Nachhilfe', 'Tutor', 'Gibt tagsüber Mathe-Nachhilfe und rechnet nachts Bremspunkte aus. Liegt meistens falsch.', 'Tutors maths by day and calculates braking points by night. Usually wrong.'),
  ('covet/15le_M', 'Hinata Oda', 'Erstsemester', 'Freshman', 'Hat das Auto von ihrer Oma geerbt. Die Oma fährt angeblich schneller.', 'Inherited the car from her grandma. Grandma is said to be faster.'),
 ]),
dict(id='t_neon', name='Ginza Neon Club', jp='銀座ネオン倶楽部', color='#ff4fd8', tier=3, region='shinagawa',
 desc=('Nachtschwärmer aus Ginza. Ihre Autos glänzen mehr, als sie fahren, aber unterschätzen sollte man sie nicht.',
       'Night owls from Ginza. Their cars shine more than they drive, but never underestimate them.'),
 leader=('moonhawk/powerglow', 'Reika Hoshino', 'Königin der Lichter', 'Queen of Lights',
   'Kennt jede Ampel in Ginza beim Namen. Ihr Moonhawk leuchtet so hell, dass Flugzeuge darauf landen wollen.',
   'Knows every traffic light in Ginza by name. Her Moonhawk glows so bright that planes try to land on it.'),
 members=[
  ('midsize/LX_sport_M', 'Mika Fujita', 'Spiegelglanz', 'Mirror Shine', 'Poliert ihr Auto nach jeder Fahrt. Auch nach jeder verlorenen. Besonders nach jeder verlorenen.', 'Polishes her car after every run. Especially after the lost ones.', 'pearl'),
  ('midsize/LX_V6_sport_M', 'Shun Arai', 'Barkeeper', 'Bartender', 'Kommt direkt von der Schicht und mixt dir nach dem Rennen einen Drink. Alkoholfrei, er ist ja Profi.', 'Comes straight from his shift and mixes you a drink after the race. Alcohol-free, he is a pro.', 'wine'),
  ('sunburst2/itasha', 'Nana Kudo', 'Leuchtreklame', 'Neon Sign', 'Ihr Unterboden leuchtet lila und ihr Auto ist mit ihrer Lieblings-Idol beklebt. Das Idol weiß nichts davon.', 'Her underbody glows purple and her car is wrapped with her favourite idol. The idol has no idea.'),
  ('miramar/luxe_coupe_A', 'Takeshi Mura', 'Der Gastgeber', 'The Host', 'Fährt mit Automatik und Stil. Hält dir nach dem Rennen die Tür auf, auch wenn du verloren hast.', 'Drives automatic, with style. Holds the door for you after the race, even when you lost.', 'champagne'),
  ('miramar/luxe_coupe_facelift_A', 'Ayumi Kanzaki', 'Pelzmantel', 'Fur Coat', 'Trägt im Sommer einen Pelzmantel. Die Klimaanlage läuft dafür auf Stufe 5.', 'Wears a fur coat in summer. The air con runs on max to make it work.'),
  ('miramar/luxe_facelift_A', 'Goro Shibata', 'Der Türsteher', 'The Bouncer', 'Lässt nur Autos mit sauberen Felgen an sich vorbei. Deine sind dreckig.', 'Only lets cars with clean wheels pass him. Yours are dirty.'),
  ('miramar/luxe_coupe_export_early_A', 'Sachiko Mine', 'Mama-san', 'Mama-san', 'Führt eine kleine Bar in Ginza und kennt jedes Geheimnis der Stadt. Deins auch.', 'Runs a small bar in Ginza and knows every secret of the city. Yours too.', 'burgundy'),
  ('midsize/LX_sport_A', 'Kaoru Nishio', 'Karaoke-König', 'Karaoke King', 'Singt beim Fahren so laut, dass seine Hupe neidisch wird.', 'Sings so loudly while driving that his horn gets jealous.'),
  ('midsize/LX_V6_sport_A', 'Erika Mochizuki', 'Glitzer', 'Glitter', 'Hat Strass-Steine auf dem Lenkrad. Lenkt deshalb nur mit Handschuhen.', 'Has rhinestones on her steering wheel. Only steers with gloves on.', 'violet'),
  ('midsize/stanced', 'Jun Tachibana', 'Tiefflieger', 'Low Flyer', 'So tief, dass er jede Fuge im Asphalt persönlich kennt. Bremsschwellen sind seine Erzfeinde.', 'So low he knows every crack in the asphalt personally. Speed bumps are his nemesis.'),
  ('fullsize/lowrider', 'Carlos Mendoza', 'Hüpfburg', 'Bounce House', 'Kam aus Los Angeles zum Studieren und blieb wegen der Karaoke. Sein Lowrider hüpft an jeder Ampel.', 'Came from Los Angeles to study and stayed for the karaoke. His lowrider hops at every light.'),
 ]),
dict(id='t_kasumi', name='Kasumi Drift Union', jp='霞ドリフトユニオン', color='#7fd6ff', tier=6, region='shizuoka',
 desc=('Drifter, die lieber quer als schnell sind. Auf dem Ring zeigen sie, dass beides geht.',
       'Drifters who would rather go sideways than fast. On the loop they show you can do both.'),
 leader=('bx/pro_drift_M', 'Kaito Shirasagi', 'Weißer Nebel', 'White Mist',
   'Man sieht ihn nur im Rauch seiner eigenen Reifen. Sein Reifenhändler hat ihm ein Ferienhaus gekauft.',
   'You only ever see him inside the smoke of his own tyres. His tyre dealer bought a holiday home off him.', 'white'),
 members=[
  ('bx/street_drift_M', 'Sota Nishida', 'Rauchzeichen', 'Smoke Signal', 'Hinterlässt immer eine Wolke. Die Feuerwehr hat ihn auf Kurzwahl.', 'Always leaves a cloud behind. The fire brigade has him on speed dial.'),
  ('miramar/drift', 'Aoi Kamiya', 'Gegenlenker', 'Countersteer', 'Lenkt schneller als sie denkt. Denkt dafür manchmal gar nicht.', 'Steers faster than she thinks. Sometimes skips the thinking entirely.'),
  ('pessima/drift', 'Ren Hayashi', 'Reifenfresser', 'Tyre Eater', 'Braucht jede Woche neue Reifen. Isst nebenbei auch gerne Gummibärchen.', 'Needs new tyres every week. Also enjoys gummy bears.'),
  ('sunburst2/drift_street', 'Yuto Kanda', 'Handbremse', 'Handbrake', 'Zieht die Handbremse auch auf der Geraden. Aus Prinzip.', 'Pulls the handbrake even on the straights. On principle.'),
  ('sunburst2/drift_pro', 'Rin Asakura', 'Winkelmesser', 'Protractor', 'Misst nach jeder Kurve den Driftwinkel nach. Unter 45 Grad zählt für sie nicht als Kurve.', 'Measures her drift angle after every corner. Under 45 degrees does not count as a corner.'),
  ('sbr/drift', 'Kohei Mizushima', 'Qualmwolke', 'Smoke Stack', 'Ist im Rauch so oft verloren gegangen, dass er jetzt ein Navi für Nebel hat.', 'Got lost in his own smoke so often that he now has a fog sat-nav.'),
  ('etki/drift', 'Lukas Brenner', 'Der Bayer', 'The Bavarian', 'Kam als Austauschstudent und hat sein Rückflugticket gegen einen Satz Reifen getauscht.', 'Came as an exchange student and traded his flight home for a set of tyres.'),
 ]),
dict(id='t_yamagumi', name='Takane Yama-Gumi', jp='高嶺山組', color='#9ccc65', tier=2, region='toyota',
 desc=('Bergleute, die mit ihren hohen Kisten in die Stadt kommen. Niemand nimmt sie ernst, bis sie vorbei sind.',
       'Mountain folk who come to the city in their tall boxes. Nobody takes them seriously until they have passed.'),
 leader=('van/offroad_alt', 'Jiro Takane', 'Der Bergkönig', 'The Mountain King',
   'Sagt, die Stadt sei nur ein flacher Berg. Kam mit seinem Bus über drei Pässe, ohne einmal zu schalten.',
   'Says the city is just a flat mountain. Drove his van over three passes without changing gear once.'),
 members=[
  ('hopper/zxt6_M', 'Goro Yamane', 'Bergziege', 'Mountain Goat', 'Fährt den Ring wie einen Pass. Hupt vor jeder Kurve, falls eine Kuh kommt.', 'Drives the loop like a mountain pass. Honks before every corner in case of cows.', 'forest'),
  ('hopper/sport_M', 'Tomoe Hirata', 'Lawine', 'Avalanche', 'Wenn sie rollt, hält sie nichts mehr auf. Auch keine Bremse.', 'Once she gets rolling, nothing stops her. Not even the brakes.'),
  ('miramar/base_ute_M', 'Isamu Kuroki', 'Holzfäller', 'Lumberjack', 'Hat noch Holz auf der Ladefläche. Das Holz ist schneller als manche Gegner.', 'Still has firewood in the bed. The firewood is faster than some rivals.'),
  ('hopper/race', 'Hana Oyama', 'Gipfelstürmerin', 'Summit Stormer', 'Hat ihren Hopper auf die Strecke gebracht. Der Hopper hat sich bis heute nicht davon erholt.', 'Took her Hopper to the track. The Hopper still has not recovered.'),
  ('hopper/lxt4_M', 'Taro Kumagai', 'Bärenfreund', 'Bear Buddy', 'Hat einen Bären als Nachbarn und behauptet, sie grüßen sich. Der Bär bestreitet das.', 'Has a bear for a neighbour and claims they wave at each other. The bear denies it.'),
  ('hopper/lxt4_A', 'Fumiko Kumagai', 'Bärenfreundin', 'Bear Buddy II', 'Taros Frau. Fährt Automatik, damit eine Hand frei bleibt für die Thermoskanne.', 'Taro\'s wife. Drives automatic to keep one hand free for the thermos.'),
  ('hopper/lxt6_M', 'Shige Nakayama', 'Schneeketten', 'Snow Chains', 'Hat das ganze Jahr Schneeketten im Kofferraum. Man weiß ja nie, sagt er, auch im August.', 'Keeps snow chains in the boot all year. You never know, he says, even in August.'),
  ('hopper/lxt6_A', 'Kiyoshi Tanizaki', 'Onsen-Opa', 'Hot Spring Grandpa', 'Fährt nach jedem Rennen direkt ins Onsen. Riecht deshalb immer leicht nach Schwefel.', 'Drives straight to the hot spring after every race. Always smells faintly of sulphur.'),
  ('hopper/zxt6_A', 'Nobu Iwasaki', 'Steinschlag', 'Rockfall', 'Seine Windschutzscheibe hat mehr Sterne als der Nachthimmel über den Alpen.', 'His windscreen has more chips than the night sky over the Alps has stars.'),
  ('hopper/sport_A', 'Yoko Fujimori', 'Pilzsammlerin', 'Mushroom Hunter', 'Kennt jeden Pilz im Wald und jede Lücke im Verkehr. Bei beiden gilt: nicht alle sind gut für dich.', 'Knows every mushroom in the woods and every gap in traffic. Not all of them are good for you.'),
  ('miramar/base_ute_facelift_M', 'Hachiro Mori', 'Reisbauer', 'Rice Farmer', 'Liefert morgens Reis und fährt nachts Rennen. Schläft angeblich im Stehen auf dem Feld.', 'Delivers rice in the morning and races at night. Supposedly sleeps standing up in the paddy.'),
  ('miramar/base_ute_plucky_M', 'Chiyo Hosokawa', 'Plucky', 'Plucky', 'Hat ihren Pick-up nach sich selbst benannt. Oder sich nach ihrem Pick-up, so genau weiß das niemand.', 'Named her pickup after herself. Or herself after the pickup, nobody is quite sure.', 'cream'),
 ]),
dict(id='t_kitsune', name='Kōsoku Kitsune', jp='高速狐', color='#ff8a3d', tier=4, region='shinagawa',
 desc=('Die Autobahnfüchse. Schlau, schnell und immer genau dort, wo man sie nicht erwartet. Ihre Autos sehen aus wie Opas Limousine, sind es aber nicht.',
       'The highway foxes. Clever, fast and always exactly where you do not expect them. Their cars look like grandpa\'s sedan, but they are not.'),
 leader=('wendover/Street_tuned', 'Shiori Kitsuneda', 'Neunschwanz', 'Nine Tails',
   'Niemand hat sie je zweimal hintereinander geschlagen. Fährt einen importierten Wendover, weil kein Mensch so etwas verdächtigt.',
   'Nobody has ever beaten her twice in a row. Drives an imported Wendover because nobody ever suspects one.'),
 members=[
  ('pessima/GTz', 'Akane Sugiyama', 'Roter Schweif', 'Red Tail', 'Lässt dich an ihrem Heck kleben, bis du müde wirst. Dann ist sie weg.', 'Lets you stick to her bumper until you get tired. Then she is gone.', 'fox'),
  ('pessima/custom', 'Hiro Matsuda', 'Der Täuscher', 'The Trickster', 'Blinkt links und fährt rechts. Hat noch nie einen Blinker richtig benutzt, aus Prinzip.', 'Signals left and goes right. Has never used an indicator correctly, on principle.'),
  ('pessima/LX_M', 'Kiko Iwata', 'Fuchsbau', 'Fox Den', 'Kennt jede Abkürzung, die es nicht gibt.', 'Knows every shortcut that does not exist.'),
  ('pessima/ZX_M', 'Masaru Endo', 'Nachtjäger', 'Night Hunter', 'Jagt nur nach Mitternacht. Vorher ist er Steuerberater.', 'Only hunts after midnight. Before that he is a tax advisor.'),
  ('pessima/ZX_4ws_M', 'Tamaki Fushimi', 'Krebsgang', 'Crab Walk', 'Ihre Hinterräder lenken mit. Sie behauptet, sie hätte ihnen das beigebracht.', 'Her rear wheels steer too. She claims she taught them.'),
  ('pessima/DX_M', 'Ginji Kuzunoha', 'Graue Maus', 'Grey Mouse', 'Sein Auto ist so unauffällig, dass selbst die Radarfallen es übersehen.', 'His car is so forgettable that even the speed cameras miss it.', 'grey'),
  ('pessima/DX_A', 'Ume Kuzunoha', 'Taxi-Tante', 'Cab Auntie', 'Ginjis Tante. Wird an jeder Ampel für ein Taxi gehalten und nimmt manchmal sogar Fahrgäste mit.', 'Ginji\'s aunt. Gets mistaken for a taxi at every light and sometimes picks up fares.', 'beige'),
  ('pessima/LX_A', 'Inari Tsuda', 'Schreinwächter', 'Shrine Keeper', 'Hängt vor jedem Rennen ein Glücksamulett an den Spiegel. Hat inzwischen 47 davon.', 'Hangs a lucky charm on his mirror before every race. He now has 47 of them.'),
 ]),
dict(id='t_akatsuki', name='Akatsuki Racing', jp='暁レーシング', color='#ff5252', tier=11, region='shinagawa',
 desc=('Ein ehemaliges Werksteam, das jetzt nur noch nachts fährt. Diszipliniert und gnadenlos, mit Rennautos, die eigentlich gar nicht auf die Straße dürften.',
       'A former works team that only races at night now. Disciplined and ruthless, in race cars that should not really be on the road.'),
 leader=('sbr/hillclimb_SQ', 'Ryo Akatsuki', 'Der Teamchef', 'The Team Boss',
   'War einmal Werksfahrer. Redet nicht darüber. Hat eine Stoppuhr um den Hals, auch beim Einkaufen.',
   'Used to be a works driver. Does not talk about it. Wears a stopwatch around his neck, even at the supermarket.'),
 members=[
  ('sunburst2/track_attack', 'Kazuki Okada', 'Das Metronom', 'The Metronome', 'Fährt jede Runde auf die Zehntel gleich. Auch seine Witze sind jedes Mal dieselben.', 'Laps within a tenth every single time. His jokes are identical every time too.'),
  ('sunburst2/trackday_M', 'Emi Tsuchiya', 'Ideallinie', 'Racing Line', 'Weicht nie einen Zentimeter von der Linie ab. Parkt auch im Supermarkt auf der Ideallinie.', 'Never deviates a centimetre from the line. Even parks on the racing line at the supermarket.'),
  ('covet/race', 'Naoki Ueda', 'Der Ingenieur', 'The Engineer', 'Hat seine Abstimmung selbst gerechnet. Auf einem Taschenrechner von 1986.', 'Calculated his setup himself. On a calculator from 1986.'),
  ('covet/turbo_race', 'Rina Kawaguchi', 'Morgenrot', 'Red Dawn', 'Fährt bis die Sonne aufgeht. Danach geht sie direkt zur Frühschicht.', 'Races until the sun comes up. Then goes straight to the early shift.', 'red'),
  ('bx/track_M', 'Shogo Hasegawa', 'Boxenfunk', 'Pit Radio', 'Redet während des Rennens ununterbrochen mit einem Teamfunk, den es nicht mehr gibt.', 'Talks non-stop into a team radio that has not existed for years.'),
  ('sbr/track', 'Mio Takagi', 'Pole Position', 'Pole Position', 'Hat in ihrer Karriere 31 Pole Positions geholt. Erzählt dir alle 31.', 'Took 31 pole positions in her career. Will tell you about all 31.'),
  ('pessima/hillclimb', 'Tatsuya Moriyama', 'Bergsprinter', 'Hill Sprinter', 'Kommt vom Bergrennen und findet den Ring zu flach. Fährt deshalb über jeden Randstein.', 'Comes from hill climbing and finds the loop too flat. So he jumps every kerb.'),
 ]),
dict(id='t_raijin', name='Raijin Garage', jp='雷神ガレージ', color='#ffe14d', tier=9, region='shinagawa',
 desc=('Tuner aus einer Werkstatt unter den Gleisen. Ihre Turbos hört man, bevor man sie sieht.',
       'Tuners from a workshop under the railway tracks. You hear their turbos before you see them.'),
 leader=('lansdale/44_tuner_special_AWD_SC_M', 'Genji Raijima', 'Der Donnergott', 'The Thunder God',
   'Hat jedes Auto der Garage selbst gebaut. Seinen Lansdale hat er aus Amerika geholt, weil ihm in Japan kein Motor mehr laut genug war.',
   'Built every car in the garage himself. Imported his Lansdale from America because no engine in Japan was loud enough anymore.'),
 members=[
  ('sbr/TT_RWD_S_M', 'Takumi Inoue', 'Donnerschlag', 'Thunderclap', 'Sein Abblasventil ist lauter als der Motor. Die Nachbarn haben eine Petition gestartet.', 'His blow-off valve is louder than his engine. The neighbours started a petition.', 'yellow'),
  ('sbr/TT_AWD_S_M', 'Mai Kobayashi', 'Blitzableiter', 'Lightning Rod', 'Nichts bringt sie aus der Ruhe. Nicht mal ein Turboschaden bei 250.', 'Nothing rattles her. Not even a blown turbo at 250.'),
  ('covet/turbo', 'Yusuke Ota', 'Funkenflug', 'Spark Shower', 'Seine Auspuffflammen sind legendär. Seine Augenbrauen nicht mehr.', 'His exhaust flames are legendary. His eyebrows are not anymore.'),
  ('sbr/TT_AWD_S_DCT', 'Sayaka Nomura', 'Gewitterfront', 'Storm Front', 'Kommt mit jedem Kilometer näher. Wie ein Gewitter. Mit Hagel.', 'Gets closer with every kilometre. Like a thunderstorm. With hail.'),
  ('sbr/TT_RWD_S_DCT', 'Daigo Kirishima', 'Ladedruck', 'Boost', 'Sagt bei jeder Begrüßung seinen aktuellen Ladedruck an. Statt Hallo.', 'Announces his current boost pressure instead of saying hello.'),
  ('sbr/custom', 'Kenji Hoshi', 'Kabelbaum', 'Wire Loom', 'Hat mehr Kabel im Auto als ein Tonstudio. Weiß nicht mehr, wofür die Hälfte ist.', 'Has more wiring in his car than a recording studio. Forgot what half of it does.'),
  ('bx/street_tuned_M', 'Haru Tsukamoto', 'Schweißnaht', 'Weld Seam', 'Schweißt tagsüber Rohre unter den Gleisen und nachts dich an die Leitplanke.', 'Welds pipes under the tracks by day and welds you to the guardrail by night.'),
  ('bx/runner_M', 'Ichiro Sakai', 'Durchläufer', 'Runner', 'Fährt seit vier Jahren mit demselben Kolbenring und betet jeden Abend für ihn.', 'Has run the same piston ring for four years and prays for it every night.'),
  ('sunburst2/street_tuned', 'Noa Fujisaki', 'Stromstoß', 'Power Surge', 'Jüngstes Mitglied der Garage. Hat ihr erstes Auto mit zwölf zerlegt, das ihres Vaters.', 'Youngest member of the garage. Took apart her first car at twelve. It was her dad\'s.'),
  ('miramar/custom', 'Tetsu Ogura', 'Altmetall', 'Scrap Iron', 'Hat einen Miramar aus dem Schrott gezogen und ihm einen Turbo verpasst. Der Miramar hat nie gefragt.', 'Pulled a Miramar out of a scrapyard and gave it a turbo. The Miramar never asked for this.'),
  ('midsize/custom', 'Kanna Shibuya', 'Drehmoment', 'Torque', 'Rechnet in Newtonmetern statt in Yen. Ihre Miete beträgt etwa 400 Nm.', 'Counts in newton metres instead of yen. Her rent is about 400 Nm.'),
 ]),
dict(id='t_kurogane', name='Kurogane-kai', jp='黒鉄会', color='#b0b0b0', tier=8, region='shinagawa',
 desc=('Schwarze Autos, keine Aufkleber, kein Wort. Die Kurogane fahren seit zwanzig Jahren auf dem Ring und haben eine Regel: Lack ist schwarz.',
       'Black cars, no stickers, no words. The Kurogane have raced the loop for twenty years and have one rule: paint is black.'),
 leader=('bolide/notte', 'Masamune Kurogane', 'Das Oberhaupt', 'The Patriarch',
   'Fuhr schon auf dem Ring, als er noch neu war. Sein Bolide heißt Notte, und so fährt er auch: man sieht ihn nicht kommen.',
   'Raced the loop when it was still new. His Bolide is called Notte and that is how he drives: you never see him coming.', 'black'),
 members=[
  ('pessima/race', 'Shinji Kuroda', 'Schwarzer Stahl', 'Black Steel', 'Sein Auto hat keine einzige Delle. Die letzte Delle hat er persönlich rausgeweint.', 'His car does not have a single dent. He cried the last one out personally.', 'black'),
  ('covet/turbo_evolution', 'Asuka Mizuno', 'Stille Klinge', 'Silent Blade', 'Sagt nie ein Wort, auch nicht nach dem Sieg. Kommuniziert ausschließlich über die Lichthupe.', 'Never says a word, not even after winning. Communicates exclusively by headlight flash.', 'black'),
  ('midsize/race', 'Tetsuya Hara', 'Eisenfaust', 'Iron Fist', 'Drängelt, bis du Platz machst. Hat noch nie Platz gemacht.', 'Tailgates until you move over. Has never once moved over himself.', 'black'),
  ('miramar/race', 'Kyoko Sato', 'Schattenriss', 'Silhouette', 'Man erkennt nur ihre Rücklichter. Manche sagen, das Auto hat gar keine Vorderseite.', 'All you ever see are her tail lights. Some say the car has no front at all.', 'black'),
  ('bx/vspecial_M', 'Ryuji Kagami', 'Spiegelbild', 'Reflection', 'Poliert seinen Lack so schwarz, dass man sich darin besser sieht als im Spiegel.', 'Polishes his paint so black you see yourself better in it than in a mirror.', 'black'),
  ('pessima/custom2', 'Ginzo Yami', 'Neumond', 'New Moon', 'Fährt nur in Nächten ohne Mond. Bei Vollmond bleibt er beleidigt zu Hause.', 'Only drives on moonless nights. At full moon he sulks at home.', 'black'),
 ]),
]
